package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.DurationFieldType;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.joda.time.impl.DurationFieldType;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_add_TriageGen1Test {

    @Test
    public void testAddWithDays() {
        // Initialize at a known date: 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Add 5 days
        dt.add(DurationFieldType.day(), 5);

        // Verify the new instant (5 days in millis)
        long expectedMillis = new MutableDateTime(2023, 1, 6, 0, 0, 0, 0).getMillis();
        assertEquals(expectedMillis, dt.getMillis());
        assertNotEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddWithMonths() {
        // Initialize at 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Add 2 months
        dt.add(DurationFieldType.month(), 2);

        assertEquals(3, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddWithYears() {
        // Initialize at 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Add 1 year
        dt.add(DurationFieldType.year(), 1);

        assertEquals(2024, dt.getYear());
    }

    @Test
    public void testAddWithHours() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 3 hours
        dt.add(DurationFieldType.hour(), 3);

        assertEquals(13, dt.getHourOfDay());
    }

    @Test
    public void testAddWithMinutes() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 30 minutes
        dt.add(DurationFieldType.minute(), 30);

        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAddWithSeconds() {
        // Initialize at 2023-01-01 10:00:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 45 seconds
        dt.add(DurationFieldType.second(), 45);

        assertEquals(45, dt.getSecondOfMinute());
    }

    @Test
    public void testAddWithMillis() {
        // Initialize at 2023-01-01 10:00:00.000
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);

        // Add 500 millis
        dt.add(DurationFieldType.millis(), 500);

        assertEquals(500, dt.getMillisOfSecond());
    }

    @Test
    public void testAddWithZeroAmount() {
        // The method contains: if (amount != 0) { ... }
        // Testing amount = 0 should result in no change (branch coverage)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();

        dt.add(DurationFieldType.day(), 0);

        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddWithNegativeAmount() {
        // Testing negative amount (subtraction)
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 10, 0, 0, 0);

        // Subtract 2 days
        dt.add(DurationFieldType.day(), -2);

        assertEquals(8, dt.getDayOfMonth());
    }
}
